class ListNode {
  constructor(val) {
    this.val = val;
    this.next = null;
  }
}

function reverseList(head) {
  let prev = null;
  while (head) {
    const next = head.next;
    head.next = prev;
    prev = head;
    head = next;
  }
  return prev;
}

function build(arr) {
  const dummy = new ListNode(0);
  let tail = dummy;
  for (const v of arr) { tail.next = new ListNode(v); tail = tail.next; }
  return dummy.next;
}
const rev = reverseList(build([1, 2, 3, 4, 5]));
const out = [];
for (let n = rev; n; n = n.next) out.push(n.val);
console.log(out.join(' '));

